import {
  WithMockedDate,
  WithResetQueryCache,
  withMockedDate,
  withQueryProvider,
  withResetQueryCache,
} from "../../../../../.storybook/preview";
import { LocalStorageHelper, throwError } from "@/core/helpers";
import { SingleMediaResponse } from "@parksandresorts/webapiproxy-types";
import {
  MOCKED_DATE,
  allMedia,
  clickOnElement,
  delay,
  fetchAlbumMock,
  typeValue,
  waitForVisibleElement,
  withFocusedMediaModalMinHeight,
} from "../digital-ride-media-storybook-helpers";
import { expect, userEvent, within } from "storybook/test";
import { ComponentProps } from "react";

const IMAGE_NUMBER_ERROR_ID = "digital-ride-media-search-card-image-number-error";

type StoryArgs = ComponentProps<WithResetQueryCache<WithMockedDate<typeof DigitalRideMediaSearchBlock>>> & {
  savedAlbumIds: Array<string>;
};

// Clear the URL hash whenever the story changes: the search form keeps its
// ride/prefix/number in the hash (useHashState), and the block reads it synchronously
// on mount. Without this, switching stories would re-show the previous story's found
// media. Guarded on the story id so we only clear on a real story switch — never
// mid-play, which would wipe the values the play function is typing.
let lastClearedStoryId: string | undefined;
const withClearedHash: Decorator = (Story, context) => {
  if (lastClearedStoryId !== context.id) {
    window.location.hash = "";
    lastClearedStoryId = context.id;
  }
  return <Story />;
};

/**
 * See `Save To Album` stories to view all options/versions for saving media to an album
 */
const meta: Meta<StoryArgs> = {
  title: "Modules/Digital Ride Media/Search Block",
  component: DigitalRideMediaSearchBlock,
  argTypes: {
    mockedDate: {
      control: {
        type: "date",
      },
    },
  },
  decorators: [withClearedHash, withResetQueryCache, withMockedDate, withQueryProvider, withFocusedMediaModalMinHeight],
  parameters: {
    chromatic: { delay: 4000 },
  },
  render: function StoryComponent({ ...args }) {
    LocalStorageHelper.setItem("savedRideMediaAlbumIds", args.savedAlbumIds, undefined);
    return (
      <QueryProvider>
        <DigitalRideMediaSearchBlock
          {...args}
          navigateToAlbum={(albumId) => action("navigateToNewAlbum")(albumId)}
          navigateToStartPage={() => action("navigateToStartPage")()}
          service={{
            searchForMedia: async (rideId, prefix, number) => {
              action("searchForMedia")(rideId, prefix, number);
              await delay(200);
              const matchedMedia = Object.values(allMedia).find((media) => media.mediaId === `01234-${number}-0000`);
              if (!matchedMedia) {
                throw new Error(`No media found for ${prefix}-${number}`);
              }
              return { item: matchedMedia } as SingleMediaResponse;
            },
            fetchAlbum: fetchAlbumMock,
            // Functions not needed for the stories
            createNewAlbumWithInitialMedia: () => throwError("Not implemented"),
            addMediaToAlbum: () => throwError("Not implemented"),
            addContactInformationToAlbum: () => throwError("Not implemented"),
            fetchAlbumMedia: () => throwError("Not implemented"),
            updateName: () => throwError("Not implemented"),
            deleteMediaFromAlbum: () => throwError("Not implemented"),
            deleteAlbum: () => throwError("Not implemented"),
            createNewAlbum: () => throwError("Not implemented"),
            getMediaOnQrCodeAccount: () => throwError("Not implemented"),
            connectQrCodeToAlbum: () => throwError("Not implemented"),
          }}
        />
      </QueryProvider>
    );
  },
};

export default meta;

type Story = StoryObj<typeof meta>;

// --- Play functions ---

/** Open the ride selector and select the first ride */
const selectRide = async ({ canvasElement }: { canvasElement: HTMLElement }) => {
  await clickOnElement({
    canvasElement,
    testId: "digital-ride-media-search-card-ride-select",
  });
  const options = await within(canvasElement).findAllByRole("option");
  expect(options.length).toBeGreaterThan(0);
  await userEvent.click(options[0]);
};

/** Enter the image number prefix */
const enterImageNumberPrefix = async ({
  canvasElement,
  imageNumberPrefix,
}: {
  canvasElement: HTMLElement;
  imageNumberPrefix: string;
}) => {
  await typeValue({
    canvasElement,
    testCases: [["digital-ride-media-search-card-image-prefix", imageNumberPrefix]],
  });
};

/** Enter the image number */
const enterImageNumber = async ({
  canvasElement,
  imageNumber,
}: {
  canvasElement: HTMLElement;
  imageNumber: string;
}) => {
  await typeValue({
    canvasElement,
    testCases: [["digital-ride-media-search-card-image-number", imageNumber]],
  });
};

/** Click the search media button */
const searchForMedia = async ({ canvasElement }: { canvasElement: HTMLElement }) => {
  await clickOnElement({
    canvasElement,
    testId: "digital-ride-media-search-album-form-search-button",
  });
};

